import React, { useState } from 'react';
import {Bar} from 'react-chartjs-2';



//Bar chart from Chart.js
function BarChart({chartData}){
  return (
    <Bar data={chartData} options={{ maintainAspectRatio: true }}/>
  )
}

export default BarChart
